---------------------
---- KEYBINDINGS ----
---------------------

-- See https://wiki.hypr.land/Configuring/Basics/Binds/
local mainMod = "SUPER" -- the "Windows" key (META is an alias for the same modmask)

hl.bind(mainMod .. " + Q",   hl.dsp.exec_cmd("~/.config/hypr/scripts/confirm-close.sh"))
hl.bind(mainMod .. " + TAB", hl.dsp.exec_cmd("~/.config/wofi/wofi-window.sh"))
hl.bind(mainMod .. " + M",   hl.dsp.exec_cmd("wlogout -b 5"))
hl.bind(mainMod .. " + E",   hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V",   hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + D",   hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P",   hl.dsp.window.pseudo())          -- dwindle
hl.bind(mainMod .. " + J",   hl.dsp.layout("togglesplit"))    -- dwindle

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness (the old `bindel` = locked + repeating)
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"),    { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),    { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl s 10%+"),                         { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl s 10%-"),                         { locked = true, repeating = true })

-- Screenshot region to clipboard
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd('grim -g "$(slurp)" - | wl-copy'))

-- Screenshot full screen to clipboard
hl.bind("Print", hl.dsp.exec_cmd("grim - | wl-copy"))

-- Clipboard history
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("cliphist list | wofi --dmenu | cliphist decode | wl-copy"))

-- Bluetooth TUI
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(terminal .. " -e bluetuith"))

-- WiFi TUI
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd(terminal .. " -e nmtui"))

-- Notification center toggle
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("swaync-client -t -sw"))


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Ignore maximize requests from all apps.
hl.window_rule({
    name           = "suppress-maximize-events",
    match          = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    match = { class = "(?i).*kcalc.*" },
    float = true,
})

hl.window_rule({
    match = {
        class = [[^(org\.remmina\.Remmina)$]],
        title = [[^(Remmina Remote Desktop Client)$]],
    },
    float = true,
})
